public class Main {
    public static void main(String[] args) {
        NameQueue line = new NameQueue(3);
        line.enqueue("Ana");
        line.enqueue("Ben");
        System.out.println("Served: " + line.dequeue());
        line.enqueue("Cy");
        line.enqueue("Dee"); // wraps around into slot 0
        while (line.size > 0) {
            System.out.println("Served: " + line.dequeue());
        }
    }
}

class NameQueue {
    String[] slots;
    int front = 0; // where the next person leaves from
    int size = 0;

    NameQueue(int capacity) {
        slots = new String[capacity];
    }

    void enqueue(String name) {
        int back = (front + size) % slots.length; // % makes the index wrap around
        slots[back] = name;
        size++;
    }

    String dequeue() {
        String name = slots[front];
        slots[front] = null;
        front = (front + 1) % slots.length;
        size--;
        return name;
    }
}
